-- Row-level security for teams, team_members and projects.

-- Membership helpers. They must be SECURITY DEFINER so that the policies on
-- team_members can ask "which teams am I in?" without recursing into their own
-- policy. They live in a non-exposed schema so they aren't callable via the
-- Data API, and they only ever answer about the calling user.
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;

create or replace function private.is_team_member(_team_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.team_members
    where team_id = _team_id and user_id = (select auth.uid())
  );
$$;

create or replace function private.is_team_admin(_team_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.team_members
    where team_id = _team_id and user_id = (select auth.uid()) and role = 'admin'
  );
$$;

revoke all on function private.is_team_member(uuid) from public;
revoke all on function private.is_team_admin(uuid) from public;
grant execute on function private.is_team_member(uuid) to authenticated;
grant execute on function private.is_team_admin(uuid) to authenticated;

alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.projects enable row level security;

-- Signed-out visitors get nothing at all.
revoke all on public.teams, public.team_members, public.projects from anon;
revoke all on public.project_overview from anon;

-- Teams: members can read. No write policies, so writes are denied to API roles.
create policy "members can view their teams"
  on public.teams for select to authenticated
  using ( private.is_team_member(id) );

-- Team members: members see their team's roster; admins add and remove members.
create policy "members can view their team's members"
  on public.team_members for select to authenticated
  using ( private.is_team_member(team_id) );

create policy "admins can add team members"
  on public.team_members for insert to authenticated
  with check ( private.is_team_admin(team_id) );

create policy "admins can remove team members"
  on public.team_members for delete to authenticated
  using ( private.is_team_admin(team_id) );

-- Projects: members read; admins create, edit and delete.
create policy "members can view their teams' projects"
  on public.projects for select to authenticated
  using ( private.is_team_member(team_id) );

create policy "admins can create projects"
  on public.projects for insert to authenticated
  with check ( private.is_team_admin(team_id) );

create policy "admins can edit projects"
  on public.projects for update to authenticated
  using ( private.is_team_admin(team_id) )
  with check ( private.is_team_admin(team_id) );

create policy "admins can delete projects"
  on public.projects for delete to authenticated
  using ( private.is_team_admin(team_id) );

-- Views bypass RLS by default; run this one as the caller so the policies apply.
alter view public.project_overview set (security_invoker = true);

